import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Given: signed in as the seeded member (cookie stored in the request context)
  const login = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });
  expect(login.status(), await login.text()).toBe(200);

  // When: sign out
  const logout = await request.post("/api/auth/logout");

  // Then: 204 and the session cookie is cleared
  expect(logout.status(), await logout.text()).toBe(204);
  const cookie = logout
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "Set-Cookie for session on sign-out").toBeTruthy();
  const value = cookie!.value;
  const cleared =
    /^session=(;|$)/.test(value) ||
    /max-age=0/i.test(value) ||
    /expires=Thu, 01 Jan 1970/i.test(value);
  expect(cleared, `session cookie should be cleared, got: ${value}`).toBe(true);
});
